import{_ as e,a as o,b as a,c as i,d as r,e as n,f as s,g as l,h as c,i as g,j as m}from"./chunks/auto-start-4.B7K2fYqk.js";import{_ as p,o as d,c as u,a5 as x}from"./chunks/framework.CcrBcQWS.js";const S=JSON.parse('{"title":"컨트롤러(Steam Deck)와 Wi-Fi 연결","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"ko/manual/operation/controller-wifi-connect.md","filePath":"ko/manual/operation/controller-wifi-connect.md","lastUpdated":1787021357000}'),h={name:"ko/manual/operation/controller-wifi-connect.md"};function f(b,t,_,y,w,k){return d(),u("div",null,[...t[0]||(t[0]=[x('<h1 id="컨트롤러-steam-deck-와-wi-fi-연결" tabindex="-1">컨트롤러(Steam Deck)와 Wi-Fi 연결 <a class="header-anchor" href="#컨트롤러-steam-deck-와-wi-fi-연결" aria-label="Permalink to &quot;컨트롤러(Steam Deck)와 Wi-Fi 연결&quot;">​</a></h1><p>STEAM DECK과 로봇 Wi-Fi를 연결하고, RBQGUI에서 로봇과 통신한 뒤 자동 시작까지 진행하는 방법입니다. 초기 자세와 전원은 먼저 <a href="./initial-pose.html">로봇 초기 자세 설정</a>에서 완료하세요.</p><h2 id="_1단계-rbqgui-앱-열기" tabindex="-1">1단계: RBQGUI 앱 열기 <a class="header-anchor" href="#_1단계-rbqgui-앱-열기" aria-label="Permalink to &quot;1단계: RBQGUI 앱 열기&quot;">​</a></h2><p>STEAM DECK 바탕화면에서 <code>RBQGUI</code> 앱을 실행합니다.</p><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+e+'" alt="RBQGUI 앱" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ RBQGUI 앱 ]</figcaption></figure><h2 id="_2단계-wi-fi-연결" tabindex="-1">2단계: Wi-Fi 연결 <a class="header-anchor" href="#_2단계-wi-fi-연결" aria-label="Permalink to &quot;2단계: Wi-Fi 연결&quot;">​</a></h2><p>로봇은 <code>RBQ_{XX}</code>(XX는 기기마다 다름) 이름의 Wi-Fi(접속 지점)를 제공합니다. STEAM DECK에서 해당 네트워크에 연결합니다.</p><ol><li><strong>Wi-Fi 연결 확인</strong> - Steam Deck에서 로봇 AP(<code>RBQ_{XX}</code>)에 연결한 뒤, RBQGUI <strong>우측 상단</strong>에 네트워크 이름과 신호 아이콘이 표시되는지 확인합니다.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+o+'" alt="RBQGUI에서 Wi-Fi 상태 확인" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Wi-Fi 메뉴 ]</figcaption></figure><ol start="2"><li><strong>로봇 네트워크 선택</strong> - 목록에서 <code>RBQ_{XX}</code>를 선택합니다. (목록에 보이지 않으면 로봇 전원과 Wi-Fi 동작 상태를 확인하세요.)</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+a+'" alt="RBQ_XX 네트워크 선택" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ RBQ_{XX} 네트워크 선택 ]</figcaption></figure><ol start="3"><li><strong>연결 확인</strong> - <code>RBQ_{XX}</code>에 <strong>연결됨</strong>으로 표시되는지 확인합니다.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+i+'" alt="RBQ_XX 연결 완료" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Wi-Fi 연결 완료 ]</figcaption></figure><h2 id="_3단계-steam-deck과-로봇-연결" tabindex="-1">3단계: STEAM DECK과 로봇 연결 <a class="header-anchor" href="#_3단계-steam-deck과-로봇-연결" aria-label="Permalink to &quot;3단계: STEAM DECK과 로봇 연결&quot;">​</a></h2><p>RBQGUI가 로봇과 통신하려면, 앱 안에서 리모트 컨트롤러-로봇 연결을 한 번 더 맺어야 합니다.</p><ol><li><strong>연결 창 열기</strong> - 상단 바 왼쪽의 <code>Remote Controller-Robot Communication Connection</code> 버튼(주황색)을 누릅니다. 연결용 팝업이 표시됩니다.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+r+'" alt="리모트 컨트롤러-로봇 통신 연결" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ 통신 연결 버튼 및 팝업 ]</figcaption></figure><ol start="2"><li><strong>Connect</strong> - 팝업에서 <code>Connect</code>를 눌러 로봇과 통신 연결을 시도합니다.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+n+'" alt="Connect 버튼" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Connect ]</figcaption></figure><ol start="3"><li><strong>연결 결과 확인</strong> - 연결이 되면 같은 위치의 <code>Remote Controller-Robot Communication Connection</code> 버튼이 <strong>녹색</strong>으로 바뀌고, 팝업에도 연결된 상태가 표시됩니다.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+s+'" alt="로봇과 연결 완료" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ 연결 완료(버튼 녹색) ]</figcaption></figure><h2 id="auto-start" tabindex="-1">4단계: 자동 시작 <a class="header-anchor" href="#auto-start" aria-label="Permalink to &quot;4단계: 자동 시작 {#auto-start}&quot;">​</a></h2><p>로봇 소프트웨어·상태를 한 번에 올리려면 자동 시작 절차를 사용합니다.</p><ol><li><strong>초기 설정 창 열기</strong> - 상단 바 왼쪽의 <code>Robot Initial Setup</code> 버튼(빨간색)을 누릅니다.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+l+'" alt="Robot Initial Setup" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Robot Initial Setup 버튼 ]</figcaption></figure><ol start="2"><li><strong>자동 시작 실행</strong> - 팝업에서 <code>Auto Start Robot</code>을 누릅니다. 잠시 후 진행 상태가 화면에 표시됩니다.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+c+'" alt="Auto Start Robot" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ Auto Start Robot ]</figcaption></figure><ol start="3"><li><strong>진행 확인</strong> - <code>Manual Setup</code> 등 항목별 상태가 갱신되는지 확인합니다. (일부만 녹색인 상태가 잠시 보일 수 있습니다.)</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+g+'" alt="자동 시작 진행 중" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ 자동 시작 진행 ]</figcaption></figure><ol start="4"><li><strong>완료 확인</strong> - 화면에 표시되는 설정 항목이 <strong>모두 녹색</strong>이면 자동 시작이 정상 완료된 것입니다.</li></ol><figure style="text-align:center;margin:0.5rem auto 1.25rem;"><img src="'+m+'" alt="자동 시작 완료" style="display:block;width:100%;max-width:100%;height:auto;margin:0 auto;border-radius:6px;box-shadow:0 1px 8px rgba(0, 0, 0, 0.07);"><figcaption style="margin-top:0.5rem;text-align:center;color:var(--vp-c-text-2, #666);font-size:0.95em;">[ 자동 시작 완료(모두 녹색) ]</figcaption></figure><div class="sb sb-warning"><div class="sb-icon"><span class="sb-warn" aria-hidden="true">⚠</span></div><div class="sb-content"><p class="custom-block-title">경고</p><p>자동 시작 후에도 설정 항목이 모두 녹색으로 바뀌지 않거나 오류가 표시되면, 주변에 사람이 없는지 확인한 뒤 <a href="../Safety/emergency-stop-procedures">비상 정지 절차</a>를 숙지하고 아래를 따르세요. 작동 전에는 <a href="../Safety/general-safety-warning-precautions">일반 안전 수칙</a>을 반드시 준수하세요.</p><ol style="margin:0.5rem 0 0 1.25rem;"><li><code>Check CAN-Bus</code>가 실패한 경우: 로봇 전원을 안전하게 끈 뒤 재시작하세요.</li><li><code>Find Home-pose</code>가 실패한 경우: <a href="../Safety/maintenance-safety">유지보수 안전</a>에 따라 평탄·안정된 면에서 다리 자세를 확인한 후 재시작하세요.</li></ol><p style="margin-top:0.75rem;">문제가 계속되면 <a href="../Troubleshooting/error-reporting">문의하기</a> 페이지에서 안내에 따라 Rainbow Robotics에 연락하세요.</p></div></div>',32)])])}const C=p(h,[["render",f]]);export{S as __pageData,C as default};
